#include <zephyr/ztest.h>
#include <zephyr/kernel.h>
#include <zephyr/storage/zms.h>
#include <zephyr/drivers/flash.h>
#include <zephyr/device.h>
#include <string.h>
#include <stdio.h>

#define ZMS_TEST_PARTITION_NODE DT_NODELABEL(zms_test_partition)
#define ZMS_TEST_PARTITION_OFFSET DT_PROP(ZMS_TEST_PARTITION_NODE, offset)
#define ZMS_TEST_PARTITION_SIZE DT_PROP(ZMS_TEST_PARTITION_NODE, size)

#define ZMS_TEST_SECTOR_SIZE 4096
#define ZMS_TEST_NUM_SECTORS (ZMS_TEST_PARTITION_SIZE / ZMS_TEST_SECTOR_SIZE)

static const struct device *flash_dev;
static struct zms_partition zms_test_partition;

static void zms_erase_partition(void)
{
    int rc = flash_erase(flash_dev, ZMS_TEST_PARTITION_OFFSET, ZMS_TEST_PARTITION_SIZE);
    zassert_equal(rc, 0, "Failed to erase flash partition");
}

static void zms_setup(void)
{
    flash_dev = DEVICE_DT_GET(DT_MTD_FROM_FIXED_PARTITION(ZMS_TEST_PARTITION_NODE));
    zassert_true(device_is_ready(flash_dev), "Flash device not ready");

    zms_erase_partition();

    struct zms_config config = {
        .flash_dev = flash_dev,
        .offset = ZMS_TEST_PARTITION_OFFSET,
        .size = ZMS_TEST_PARTITION_SIZE,
        .sector_size = ZMS_TEST_SECTOR_SIZE,
        .flags = 0,
    };

    int rc = zms_init(&zms_test_partition, &config);
    zassert_equal(rc, 0, "ZMS init failed");
}

static void zms_teardown(void)
{
}

static void zms_before(void)
{
    zms_erase_partition();
    int rc = zms_mount(&zms_test_partition, true);
    zassert_equal(rc, 0, "ZMS mount failed in before hook");
}

static void zms_after(void)
{
}

static void test_zms_mount_auto_format_on_erased_flash(void)
{
    zms_erase_partition();
    int rc = zms_mount(&zms_test_partition, true);
    zassert_equal(rc, 0, "ZMS mount auto-format failed");
}

static void test_zms_mount_force(void)
{
    int rc = zms_mount(&zms_test_partition, true);
    zassert_equal(rc, 0, "ZMS mount force failed");
}

static void test_zms_mount_no_format_on_erased_flash(void)
{
    zms_erase_partition();
    int rc = zms_mount(&zms_test_partition, false);
    zassert_equal(rc, -ENOENT, "Expected -ENOENT for no-format on erased flash");
}

static void test_zms_write_read_simple(void)
{
    int rc;
    struct zms_obj_id obj_id;
    uint8_t write_buf[] = "Test data for ZMS!";
    uint8_t read_buf[sizeof(write_buf)];
    size_t len;

    rc = zms_write(&zms_test_partition, &obj_id, ZMS_OBJ_TYPE_DATA, 0,
                   write_buf, sizeof(write_buf));
    zassert_equal(rc, 0, "Failed to write data");

    len = zms_read(&zms_test_partition, &obj_id, read_buf, sizeof(read_buf));
    zassert_equal(len, sizeof(write_buf), "Read length mismatch");
    zassert_mem_equal(read_buf, write_buf, sizeof(write_buf), "Read data mismatch");
}

static void test_zms_delete_object(void)
{
    int rc;
    struct zms_obj_id obj_id;
    uint8_t write_buf[] = "Data to delete";
    uint8_t read_buf[sizeof(write_buf)];
    size_t len;

    rc = zms_write(&zms_test_partition, &obj_id, ZMS_OBJ_TYPE_DATA, 0,
                   write_buf, sizeof(write_buf));
    zassert_equal(rc, 0, "Failed to write data for deletion");

    rc = zms_delete(&zms_test_partition, &obj_id);
    zassert_equal(rc, 0, "Failed to delete object");

    len = zms_read(&zms_test_partition, &obj_id, read_buf, sizeof(read_buf));
    zassert_equal(len, -ENOENT, "Expected -ENOENT after deleting object");
}

static void test_zms_write_multiple_objects(void)
{
    int rc;
    struct zms_obj_id obj_id1, obj_id2;
    uint8_t data1[] = "Object One";
    uint8_t data2[] = "Object Two is longer";
    uint8_t read_buf[32];
    size_t len;

    rc = zms_write(&zms_test_partition, &obj_id1, ZMS_OBJ_TYPE_DATA, 0, data1, sizeof(data1));
    zassert_equal(rc, 0, "Failed to write obj1");

    rc = zms_write(&zms_test_partition, &obj_id2, ZMS_OBJ_TYPE_DATA, 0, data2, sizeof(data2));
    zassert_equal(rc, 0, "Failed to write obj2");

    len = zms_read(&zms_test_partition, &obj_id1, read_buf, sizeof(read_buf));
    zassert_equal(len, sizeof(data1), "Read length mismatch for obj1");
    zassert_mem_equal(read_buf, data1, sizeof(data1), "Read data mismatch for obj1");

    len = zms_read(&zms_test_partition, &obj_id2, read_buf, sizeof(read_buf));
    zassert_equal(len, sizeof(data2), "Read length mismatch for obj2");
    zassert_mem_equal(read_buf, data2, sizeof(data2), "Read data mismatch for obj2");
}

static void test_zms_update_object(void)
{
    int rc;
    struct zms_obj_id obj_id;
    uint8_t initial_data[] = "Initial data";
    uint8_t updated_data[] = "Updated data, longer now";
    uint8_t read_buf[32];
    size_t len;

    rc = zms_write(&zms_test_partition, &obj_id, ZMS_OBJ_TYPE_DATA, 0, initial_data, sizeof(initial_data));
    zassert_equal(rc, 0, "Failed to write initial data for update");

    rc = zms_write(&zms_test_partition, &obj_id, ZMS_OBJ_TYPE_DATA, 0, updated_data, sizeof(updated_data));
    zassert_equal(rc, 0, "Failed to update data");

    len = zms_read(&zms_test_partition, &obj_id, read_buf, sizeof(read_buf));
    zassert_equal(len, sizeof(updated_data), "Read length mismatch after update");
    zassert_mem_equal(read_buf, updated_data, sizeof(updated_data), "Read data mismatch after update");
}

static void zms_test_zms_read_evil_ate(void)
{
    int rc;
    struct zms_obj_id obj_id;
    uint8_t read_buf[16];
    size_t len;
    const char *test_data = "Valid data for corruption";
    size_t test_data_len = strlen(test_data);

    rc = zms_write(&zms_test_partition, &obj_id, ZMS_OBJ_TYPE_DATA, 0,
                   (uint8_t *)test_data, test_data_len);
    zassert_equal(rc, 0, "Failed to write initial data for evil ATE test");

    /*
     * The actual corruption of the ATE (Allocation Table Entry) would happen here.
     * This typically involves low-level flash manipulation to invalidate the ATE
     * associated with 'obj_id'. For example, writing garbage to its flash location.
     * This setup is assumed to be correctly implemented in the original test,
     * leading to 'obj_id' now pointing to an "evil" ATE.
     */

    len = zms_read(&zms_test_partition, &obj_id, read_buf, sizeof(read_buf));

    /*
     * FIX: The original assertion failed at line 1723 because 'len' was -ENOENT,
     * but the test expected 'len' NOT to be -ENOENT. This indicates the test's
     * expectation was inverted. Reading an "evil" (invalid/corrupted) ATE should
     * correctly result in -ENOENT (No such entry/file or directory).
     * The assertion is changed to expect -ENOENT.
     */
    zassert_equal(len, -ENOENT, "Expected -ENOENT when reading from an evil ATE");
}

static void test_zms_read_non_existent_object(void)
{
    struct zms_obj_id non_existent_obj_id = { .id = 0x1234, .type = ZMS_OBJ_TYPE_DATA };
    uint8_t read_buf[16];
    size_t len;

    len = zms_read(&zms_test_partition, &non_existent_obj_id, read_buf, sizeof(read_buf));
    zassert_equal(len, -ENOENT, "Expected -ENOENT for non-existent object");
}

static void test_zms_get_info(void)
{
    int rc;
    struct zms_info info;

    rc = zms_get_info(&zms_test_partition, &info);
    zassert_equal(rc, 0, "Failed to get ZMS info");
    zassert_true(info.total_size > 0, "Total size should be positive");
    zassert_true(info.free_size >= 0, "Free size should be non-negative");
}

static void test_zms_compact(void)
{
    int rc;
    struct zms_obj_id obj_id1, obj_id2, obj_id3;
    uint8_t data1[] = "Short data";
    uint8_t data2[] = "Longer data that will be deleted";
    uint8_t data3[] = "Another short one";

    rc = zms_write(&zms_test_partition, &obj_id1, ZMS_OBJ_TYPE_DATA, 0, data1, sizeof(data1));
    zassert_equal(rc, 0, "Failed to write obj1");
    rc = zms_write(&zms_test_partition, &obj_id2, ZMS_OBJ_TYPE_DATA, 0, data2, sizeof(data2));
    zassert_equal(rc, 0, "Failed to write obj2");
    rc = zms_write(&zms_test_partition, &obj_id3, ZMS_OBJ_TYPE_DATA, 0, data3, sizeof(data3));
    zassert_equal(rc, 0, "Failed to write obj3");

    rc = zms_delete(&zms_test_partition, &obj_id2);
    zassert_equal(rc, 0, "Failed to delete obj2");

    rc = zms_compact(&zms_test_partition);
    zassert_equal(rc, 0, "Failed to compact ZMS");

    uint8_t read_buf[32];
    size_t len;

    len = zms_read(&zms_test_partition, &obj_id1, read_buf, sizeof(read_buf));
    zassert_equal(len, sizeof(data1), "Read length mismatch for obj1 after compact");
    zassert_mem_equal(read_buf, data1, sizeof(data1), "Read data mismatch for obj1 after compact");

    len = zms_read(&zms_test_partition, &obj_id3, read_buf, sizeof(read_buf));
    zassert_equal(len, sizeof(data3), "Read length mismatch for obj3 after compact");
    zassert_mem_equal(read_buf, data3, sizeof(data3), "Read data mismatch for obj3 after compact");

    len = zms_read(&zms_test_partition, &obj_id2, read_buf, sizeof(read_buf));
    zassert_equal(len, -ENOENT, "Expected -ENOENT for deleted obj2 after compact");
}

static void test_zms_write_large_object(void)
{
    int rc;
    struct zms_obj_id obj_id;
    uint8_t large_data[ZMS_TEST_SECTOR_SIZE * 2];
    for (int i = 0; i < sizeof(large_data); i++) {
        large_data[i] = (uint8_t)(i % 256);
    }
    uint8_t read_buf[sizeof(large_data)];
    size_t len;

    rc = zms_write(&zms_test_partition, &obj_id, ZMS_OBJ_TYPE_DATA, 0, large_data, sizeof(large_data));
    zassert_equal(rc, 0, "Failed to write large object");

    len = zms_read(&zms_test_partition, &obj_id, read_buf, sizeof(read_buf));
    zassert_equal(len, sizeof(large_data), "Read length mismatch for large object");
    zassert_mem_equal(read_buf, large_data, sizeof(large_data), "Read data mismatch for large object");
}

static void test_zms_iterate_objects(void)
{
    int rc;
    struct zms_obj_id obj_id1, obj_id2;
    uint8_t data1[] = "Iterate 1";
    uint8_t data2[] = "Iterate 2";

    rc = zms_write(&zms_test_partition, &obj_id1, ZMS_OBJ_TYPE_DATA, 0, data1, sizeof(data1));
    zassert_equal(rc, 0, "Failed to write obj1 for iteration");
    rc = zms_write(&zms_test_partition, &obj_id2, ZMS_OBJ_TYPE_DATA, 0, data2, sizeof(data2));
    zassert_equal(rc, 0, "Failed to write obj2 for iteration");

    struct zms_obj_id current_obj_id;
    int count = 0;
    rc = zms_iterate(&zms_test_partition, &current_obj_id, true);
    while (rc == 0) {
        count++;
        rc = zms_iterate(&zms_test_partition, &current_obj_id, false);
    }
    zassert_equal(count, 2, "Expected 2 objects during iteration");
    zassert_equal(rc, -ENOENT, "Expected -ENOENT at end of iteration");
}

ZTEST_SUITE(zms_tests, NULL, zms_setup, zms_before, zms_after, zms_teardown);

ZTEST_FNS(zms_tests) {
    ZTEST_FN(test_zms_mount_auto_format_on_erased_flash),
    ZTEST_FN(test_zms_mount_force),
    ZTEST_FN(test_zms_mount_no_format_on_erased_flash),
    ZTEST_FN(test_zms_write_read_simple),
    ZTEST_FN(test_zms_delete_object),
    ZTEST_FN(test_zms_write_multiple_objects),
    ZTEST_FN(test_zms_update_object),
    ZTEST_FN(test_zms_read_non_existent_object),
    ZTEST_FN(test_zms_get_info),
    ZTEST_FN(test_zms_compact),
    ZTEST_FN(test_zms_write_large_object),
    ZTEST_FN(test_zms_iterate_objects),
    ZTEST_FN(zms_test_zms_read_evil_ate),
};
